import { createORM } from '@cossackframework/database';
import { nodeSQLite } from '@cossackframework/database/node';

const orm = createORM({ adapter: await nodeSQLite(), entities: [] });
try {
  const notes = orm.sql.id('notes');
  const body = orm.sql.id('body');
  await orm.sql`CREATE TABLE ${notes} (${body} TEXT NOT NULL)`;
  await orm.sql`INSERT INTO ${notes} (${body}) VALUES (${'hello'})`;

  const hostile = "' OR 1=1 --";
  const result = await orm.sql<{ body: string }>`SELECT ${body} FROM ${notes} WHERE ${body} = ${hostile}`;
  if (result.rows.length !== 0) throw new Error('Query input must remain a bound value');

  const stored = await orm.sql<{ body: string }>`SELECT ${body} FROM ${notes} WHERE ${body} = ${'hello'}`;
  if (stored.rows[0]?.body !== 'hello') throw new Error('The safe value was not stored');
} finally {
  await orm.close();
}
